218	inline Point2d get_normal_at_s(Line l, float s) {
219	  float tangent = get_tangent_angle_at_s(l, s);
220	  Point2d t(cos(tangent+asin(1)), sin(tangent+asin(1)));  // rotate unit vector anti-clockwise with angle = tangent by 1/2 pi
221	  return t;
222	}
