237	inline std::tuple<Point2d, double, uint> get_nearest_point_and_s(Line l, const Point2d &p) {  // get_nearest_point
238	  // edge cases: empty or one-point line
239	  if (l.obj_.empty()) {
240	    return std::make_tuple(Point2d(0, 0), 0.0, 0);
241	  } else if (l.obj_.size() == 1) {
242	    return std::make_tuple(l.obj_.at(0), 0.0, 0);
243	  }
244	
245	  // nominal case:
246	  // check distance to each line segment and find closest segment
247	  double min_dist = boost::numeric::bounds<float>::highest();
